import { useState } from 'react';
import { Button, Dialog } from '@gravity-ui/uikit';

export function App() {
  const [open, setOpen] = useState(false);

  const handleConfirm = () => {
    setOpen(false);
  };

  return (
    <div style={{ padding: 24 }}>
      <Button view="action" size="l" onClick={() => setOpen(true)}>
        Открыть диалог
      </Button>
      <Dialog open={open} onClose={() => setOpen(false)} size="s" aria-label="Подтверждение действия">
        <Dialog.Header caption="Подтверждение" />
        <Dialog.Body>
          Вы уверены, что хотите выполнить это действие? Его нельзя будет отменить.
        </Dialog.Body>
        <Dialog.Footer
          onClickButtonApply={handleConfirm}
          onClickButtonCancel={() => setOpen(false)}
          textButtonApply="Подтвердить"
          textButtonCancel="Отмена"
        />
      </Dialog>
    </div>
  );
}
```

